parameters.jsCode:
// INCREMENTAL, KEYED ON hs_lastmodifieddate. HubSpot bumps that timestamp on ANY change, so one
// filter carries both cases: a new contact is modified when it is created, an edited one when it
// is edited. Both come back, and the upsert on hs_object_id inserts the first and overwrites the
// second. Nothing ever asks Supabase which records it already holds — that would be one query per
// record.
//
// THE FLOOR IS THE EPOCH, NOT A RECENT DATE. A recent floor silently skips every contact last
// touched before it — one edited in 2023 and left alone would never sync, and nothing would report
// it missing. On the first run the table is empty, so this pulls full history; after that the
// watermark takes over and runs are small.
const FLOOR = 0;

// The watermark is rewound a minute. HubSpot's clock and ours are not the same clock, and a record
// modified in the same second the previous run read its last page would otherwise fall in the gap
// between runs and never be seen again. Re-reading a minute costs nothing — the write is an upsert.
const REWIND_MS = 60 * 1000;

const state = {};
for (const r of $input.all()) {
  const j = r.json || {};
  if (j.source) state[j.source] = j.newest_modified;
}

// POST {"since":"2026-01-01"} to the webhook to re-read a period on purpose — after a mapping
// change, or to repair a gap — without truncating the table. The schedule and the manual trigger
// carry no body and ignore it.
let override = null;
try {
  const body = $('Webhook: Sync now').first().json.body || {};
  const t = body.since ? Date.parse(body.since) : NaN;
  if (Number.isFinite(t)) override = t;
} catch (e) { /* not triggered by the webhook */ }

const v = state.contacts ? Date.parse(state.contacts) : NaN;
const since = override !== null
  ? String(override)
  : String(Number.isFinite(v) ? Math.max(FLOOR, v - REWIND_MS) : FLOOR);

return [{ json: { since_contacts: since } }];

