// HubSpot search pages come back as { results: [...] }; flatten them into the row shape
// hubspot.hubspot_contacts expects.
const rows = [];
for (const item of $input.all()) {
  for (const r of (item.json.results || [])) {
    const p = r.properties || {};
    rows.push({
      hs_object_id: Number(r.id),
      email: p.email || null,
      firstname: p.firstname || null,
      lastname: p.lastname || null,
      company: p.company || null,
      state: p.state || null,
      lifecyclestage: p.lifecyclestage || null,
      hs_lastmodifieddate: p.hs_lastmodifieddate || null,
      synced_at: new Date().toISOString(),
    });
  }
}
// ONE item carrying the whole batch. The upsert below takes the array as a single parameter, and
// ten thousand separate statements is not a sync, it is an outage.
return rows.length ? [{ json: { rows } }] : [];
